(7588512, 1223051, 38032, '<td valign="top">Yes maybe just take some of the muddy color our of the water on this one?!</td>', 'Yes maybe just take some of the muddy color our of the water on this one?!', '2018-08-02 12:36:07.000000', NULL, 1),
(7589891, 1223497, 113411, '<td valign="top">How fabulous !!!</td>', 'How fabulous !!!', '2018-08-06 01:17:38.000000', NULL, 1),
(7589917, 1223777, 87808, '<td valign="top">It kinda looks more like an overlay/texture, too perfect. but the happy couple steal the show! 6</td>', 'It kinda looks more like an overlay/texture, too perfect. but the happy couple steal the show! 6', '2018-08-06 02:03:11.000000', NULL, 1),
(7589918, 1223656, 114285, '<td valign="top">Its probably such a shame that you had to spend so much time producing this image and probably not be rewarded for it so Ill give you at least a six for your effort, even though it clearly does not meet the spirit of the challenge ;)</td>', 'Its probably such a shame that you had to spend so much time producing this image and probably not be rewarded for it so Ill give you at least a six for your effort, even though it clearly does not meet the spirit of the challenge ;)', '2018-08-06 02:04:34.000000', NULL, 1),
(7589919, 1223667, 114285, '<td valign="top">Epic processing and beautiful light.</td>', 'Epic processing and beautiful light.', '2018-08-06 02:05:06.000000', NULL, 1),
(7589920, 1223676, 87808, '<td valign="top">That look like an overlay/texture, and not in a good way. at least you could have blurred out the round earth that this is from.</td>', 'That look like an overlay/texture, and not in a good way. at least you could have blurred out the round earth that this is from.', '2018-08-06 02:05:14.000000', NULL, 1),
(7589922, 1223436, 114285, '<td valign="top">Looks like you completely missed focus on the mountain, although I guess it is a weather challenge and maybe youre focusing on the cloud, but it doesnt really work for me.</td>', 'Looks like you completely missed focus on the mountain, although I guess it is a weather challenge and maybe youre focusing on the cloud, but it doesnt really work for me.', '2018-08-06 02:06:08.000000', NULL, 1),
(7589923, 1223737, 87808, '<td valign="top">Really fun idea, and you certainly took some time to set this up. 9</td>', 'Really fun idea, and you certainly took some time to set this up. 9', '2018-08-06 02:06:19.000000', NULL, 1),
(7589928, 1223674, 87808, '<td valign="top">This is what my veggie patch looks like too. What is worse, I planted 9328752938475 Pepper Plants, Corn Plants, flowers, cucumber, melon , tomato and watermelon seeds and plants.  And I only have 1 stick of sweetcorn coming out and some bird seed, that my son thought would be a ''great'' idea at the time to plant. I have watered, looked longingly, sang and basically told them off for not growing.  And then I caught my favorite dog, trying to take a poop on my 1 stick of sweetcorn plant today.  So I feel your pain here,,,,,,,,,,,8</td>', 'This is what my veggie patch looks like too. What is worse, I planted 9328752938475 Pepper Plants, Corn Plants, flowers, cucumber, melon , tomato and watermelon seeds and plants.  And I only have 1 stick of sweetcorn coming out and some bird seed, that my son thought would be a ''great'' idea at the time to plant. I have watered, looked longingly, sang and basically told them off for not growing.  And then I caught my favorite dog, trying to take a poop on my 1 stick of sweetcorn plant today.  So I feel your pain here,,,,,,,,,,,8', '2018-08-06 02:17:40.000000', NULL, 1),
(7589939, 1223676, 114285, '<td valign="top">Had a bit of potential but the buildings are quite soft and processing is way over the top.</td>', 'Had a bit of potential but the buildings are quite soft and processing is way over the top.', '2018-08-06 02:35:31.000000', NULL, 1),
(7589952, 1223811, 87808, '<td valign="top">This is an outstanding shot, I can see the flooding, I can feel the drama, but for some reason, it is not dramatic, even though it is. And I can see that it is. And I am not sure what is needed to make this the impactfull shot it needs to be.</td>', 'This is an outstanding shot, I can see the flooding, I can feel the drama, but for some reason, it is not dramatic, even though it is. And I can see that it is. And I am not sure what is needed to make this the impactfull shot it needs to be.', '2018-08-06 03:22:03.000000', NULL, 1),
